internal/config/config.go
package config

// Redaction configures the redaction stage.
type Redaction struct {
	ModeByTarget map[string]string `yaml:"mode_by_target,omitempty"`
	Categories map[string]string `yaml:"categories,omitempty"`
	Dictionary string `yaml:"dictionary,omitempty"`
	NeverMask []string `yaml:"never_mask,omitempty"`
	Detectors []string `yaml:"detectors,omitempty"`
	FailClosed *bool `yaml:"fail_closed,omitempty"`
}

// FailClosedOn reports whether a detector failure blocks the request.
func (r Redaction) FailClosedOn() bool {
	return r.FailClosed == nil || *r.FailClosed
}

